package io.github.devicebridge.android;
import android.content.Context;import android.graphics.*;import android.view.*;import android.widget.*;import io.github.devicebridge.core.DeviceParsers;import java.util.Locale;
/** Device memory legend; missing MemAvailable is never presented as a measured zero. */
final class MemoryUsageView extends LinearLayout {
 private final TextView used,available,title;private final UsageBar bar;
 MemoryUsageView(Context c){super(c);setOrientation(VERTICAL);setPadding(Ui.dp(c,24),Ui.dp(c,24),Ui.dp(c,24),Ui.dp(c,28));title=new TextView(c);title.setText("设备内存");title.setTextSize(19);title.setTextColor(0xff101010);addView(title);bar=new UsageBar(c);LayoutParams bp=new LayoutParams(-1,Ui.dp(c,16));bp.topMargin=Ui.dp(c,18);bp.bottomMargin=Ui.dp(c,12);addView(bar,bp);used=legend("已用内存",0xff03a9f4);available=legend("可用内存",0xff9e9e9e);}
 private TextView legend(String name,int color){Context c=getContext();LinearLayout row=Ui.row(c);View square=new View(c);square.setBackgroundColor(color);row.addView(square,new LayoutParams(Ui.dp(c,16),Ui.dp(c,16)));TextView label=new TextView(c);label.setText(name);label.setTextSize(17);label.setTextColor(0xff101010);LayoutParams lp=new LayoutParams(0,-2,1);lp.leftMargin=Ui.dp(c,8);row.addView(label,lp);TextView value=new TextView(c);value.setText("读取中…");value.setTextSize(14);value.setTextColor(0xff757575);row.addView(value);LayoutParams rp=new LayoutParams(-1,Ui.dp(c,40));addView(row,rp);return value;}
 void bind(DeviceParsers.MemoryInfo memory){used.setText(human(memory.usedBytes));available.setText(human(memory.availableBytes));title.setContentDescription("设备内存，总量 "+human(memory.totalBytes)+(memory.frameworkAvailability?"；可用内存由目标系统 ActivityManager 提供":"；可用内存由目标内核 MemAvailable 提供"));available.setContentDescription("可用内存 "+human(memory.availableBytes)+(memory.frameworkAvailability?"，由目标系统 ActivityManager 提供":""));bar.fraction=memory.usedBytes!=null&&memory.totalBytes!=null&&memory.totalBytes>0?(float)memory.usedBytes/memory.totalBytes:-1;bar.setContentDescription("已用内存 "+human(memory.usedBytes)+"，可用内存 "+human(memory.availableBytes));bar.invalidate();}
 private static String human(Long value){if(value==null)return "未提供";return value<1073741824L?String.format(Locale.ROOT,"%.1f MB",value/1048576d):String.format(Locale.ROOT,"%.2f GB",value/1073741824d);}
 private static final class UsageBar extends View {final Paint paint=new Paint(3);float fraction=-1;UsageBar(Context c){super(c);}protected void onDraw(Canvas canvas){RectF rect=new RectF(0,0,getWidth(),getHeight());paint.setColor(0xff9e9e9e);canvas.drawRoundRect(rect,getHeight()/2f,getHeight()/2f,paint);if(fraction>=0){canvas.save();Path clip=new Path();clip.addRoundRect(rect,getHeight()/2f,getHeight()/2f,Path.Direction.CW);canvas.clipPath(clip);paint.setColor(0xff03a9f4);canvas.drawRect(0,0,Math.min(1,Math.max(0,fraction))*getWidth(),getHeight(),paint);canvas.restore();}}}
}
